cd "$W" || exit 1
python3 - <<'PY'

import re
def _read():
    try:
        return open('answer.txt').read()
    except OSError:
        return ''
def get(key, txt=None):
    if txt is None: txt=_read()
    m=re.search(r'(?im)^\s*'+re.escape(key)+r'\s*[=:]\s*(.+?)\s*$', txt)
    return m.group(1).strip() if m else None

