    try:
        ok = mac.strip().lower()==rogue_mac.lower() and int(re.sub(r'\D','',pr))==rogue_priority
    except Exception: ok=False
print('PASS' if ok else 'FAIL: bridge=%r priority=%r (want %r / %d)' % (mac,pr,rogue_mac,rogue_priority))
